-- Migration 023: Seed default Onboarding Week 1-8 message templates
-- Mentors can customize via Dashboard → Onboard Msgs tab
-- Uses ON CONFLICT DO NOTHING so existing customized content is preserved

INSERT INTO onboarding_messages (week_number, message_text) VALUES

(1, E'🎉 ยินดีต้อนรับสู่ BNI IDEAL!\n\nสัปดาห์ที่ 1 — เริ่มต้นอย่างดี\n────────────────────\nสิ่งสำคัญที่ควรทำในสัปดาห์นี้:\n\n1️⃣ แนะนำตัวกับทุกคนในทีม\n2️⃣ ส่ง Referral อย่างน้อย 1 ใบ\n3️⃣ นัด 1-2-1 กับสมาชิกใหม่อีก 2 คน\n\n💡 เคล็ดลับ: BNI ทำงานได้ดีที่สุดเมื่อทุกคนรู้จักกัน เริ่มจากการพูดคุยเลยครับ!\n\nมีคำถามอะไรพิมพ์หา Mentor ได้เลยนะครับ 😊'),

(2, E'📅 สัปดาห์ที่ 2 — สร้างนิสัย BNI\n────────────────────\nสิ่งสำคัญสัปดาห์นี้:\n\n✅ เข้าประชุมตรงเวลาทุกครั้ง (คะแนน 15pt)\n🤝 1-2-1 อีกอย่างน้อย 2 คน\n📢 เตรียม Referral ที่ดีสำหรับสัปดาห์หน้า\n\n💡 เคล็ดลับ: Referral ที่ดีต้องรู้จักธุรกิจของเพื่อนสมาชิก ลองถามว่า "ลูกค้า ideal ของคุณเป็นอย่างไร?"\n\nพิมพ์ "สถานะ" ดูคะแนนล่าสุดได้เลยครับ'),

(3, E'📊 สัปดาห์ที่ 3 — เข้าใจ PALMS Score\n────────────────────\nคะแนน BNI มาจาก 6 หมวด:\n\n📌 ขาดประชุม  max 15pt\n📌 Referral   max 15pt\n📌 1-2-1      max 15pt\n📌 Visitor    max 20pt\n📌 CEU        max 20pt\n📌 TYFCB      max 15pt\n\n🎯 เป้าหมาย: ≥70pt = เขียว (สมาชิกที่แข็งแกร่ง)\n\n💡 เคล็ดลับ: Visitor (20pt) คือหมวดที่ให้คะแนนมากที่สุด ลองชวนคนรู้จักมาดูประชุมสัปดาห์หน้าครับ!\n\nพิมพ์ "สถานะ" ดูว่าหมวดไหนต้องพัฒนาครับ'),

(4, E'🎯 สัปดาห์ที่ 4 — Visitor คือโอกาส\n────────────────────\nทำไม Visitor ถึงสำคัญ?\n\n✅ ให้คะแนนสูงสุด 20pt (ต่อเดือน)\n✅ Visitor อาจกลายเป็นสมาชิกใหม่\n✅ สมาชิกใหม่ = Network ที่ใหญ่ขึ้น\n\nสิ่งที่ทำได้สัปดาห์นี้:\n👥 ชวนลูกค้า เพื่อน หรือคนรู้จัก มาดูประชุม 1 คน\n🤝 นัด 1-2-1 เพิ่มอีก 2 คน\n\n💡 วิธีชวน: "เพื่อนทำธุรกิจอยู่ใช่ไหม? มีกลุ่มนักธุรกิจที่ดีมาก ลองมาดูสัปดาห์หน้าได้เลยครับ"\n\nสัปดาห์ที่ 1 เดือนแรกจบแล้ว เยี่ยมมาก! 🎉'),

(5, E'🚀 สัปดาห์ที่ 5 — Referral อย่างมืออาชีพ\n────────────────────\nReferral ที่ดีต้องมี 3 สิ่ง:\n\n1️⃣ ชื่อ-เบอร์โทรผู้รับ Referral\n2️⃣ บอกเพื่อนสมาชิกล่วงหน้าว่าจะส่งให้\n3️⃣ Follow-up ผลหลังส่ง 2 สัปดาห์\n\n🎯 เป้าหมาย: Referral ≥ 2 ใบ/สัปดาห์ = 15pt!\n\n💡 เคล็ดลับ: ถามตัวเองทุกเช้าว่า "วันนี้ใครที่ฉันรู้จักน่าจะได้ประโยชน์จากสมาชิก BNI คนไหน?"\n\nพิมพ์ "ทีม" ดูว่าทีมคุณเป็นอย่างไรบ้างครับ'),

(6, E'💡 สัปดาห์ที่ 6 — CEU คืออะไร?\n────────────────────\nCEU = Continuing Education Unit\nได้จากการเข้าร่วมกิจกรรม BNI:\n\n✅ เข้าร่วม BNI Training\n✅ นำเสนอ Featured Presentation\n✅ เข้า Chapter Edu. Moment\n✅ เป็น Visitor ที่ Chapter อื่น\n\n🎯 เป้า CEU: ≥4 ต่อ 6 เดือน = 20pt!\n\n💡 เคล็ดลับ: ดูตารางกิจกรรม BNI ในกลุ่ม LINE Chapter ของเราครับ\n\nสัปดาห์นี้มีกิจกรรมอะไรบ้าง? ถามทีม Mentor ได้เลยครับ'),

(7, E'📈 สัปดาห์ที่ 7 — ทบทวนครึ่งทาง\n────────────────────\nถึงเวลาเช็คสถานะ!\n\nพิมพ์ "สถานะ" ดูคะแนนตอนนี้\nพิมพ์ "ประวัติ" ดู Trend การพัฒนา\nพิมพ์ "ทีม" ดูว่าอยู่อันดับไหน\n\nสิ่งที่ทำได้สัปดาห์นี้:\n✅ 1-2-1 กับสมาชิกที่ยังไม่ได้คุย\n✅ ชวน Visitor มาอีกครั้ง\n✅ ส่ง Referral อย่างน้อย 2 ใบ\n\n💡 เคล็ดลับ: ถ้าคะแนนยังไม่ถึงเป้า ให้โฟกัสที่หมวดที่ได้คะแนนต่ำสุดก่อนครับ'),

(8, E'🏆 สัปดาห์ที่ 8 — จบ Onboarding แล้ว! ยอดเยี่ยม!\n────────────────────\nคุณผ่าน 8 สัปดาห์แรกมาแล้วครับ!\n\nสิ่งที่คุณทำได้แล้ว:\n✅ เข้าใจระบบ PALMS Score\n✅ เริ่มสร้าง Network\n✅ ส่ง Referral และทำ 1-2-1\n✅ ชวน Visitor เข้า Chapter\n\n🎯 ก้าวต่อไป:\nตั้งเป้า ≥70pt ให้ได้ภายในเดือนหน้าครับ\n\n💡 จากนี้ Mentor จะ Check-in กับคุณต่อเนื่อง\nมีอะไรสงสัยพิมพ์หาได้ตลอดนะครับ 😊\n\nยินดีด้วยและขอให้สำเร็จครับ! 🎉')

ON CONFLICT (week_number) DO NOTHING;
